import { TransformNode, SceneLoader } from '@babylonjs/core';
import { applyModelPaint } from '../../../utils/modelPaint.js';

// Medium doctrine standard hull — ORIGINAL mesh (Panzer III M-inspired, approved
// mockup B): boxy slabs, stepped front, Schuerzen skirt plates, front drive sprocket.
// Generated by scripts/modelgen/medium_hull_standard.py.

const PAINT = { paintColor: [0.78, 0.66, 0.43] };  // medium doctrine desert sand

export default {
  id: 'medium-hull-standard',
  name: 'Medium Hull',
  category: 'hull',
  stats: {},
  mountEmpty: 'turret',
  nativeTurret: 'medium-turret-angular',
  ringDiameter: 1.8,   // mirrors ringD in scripts/modelgen/params/
  footprint: { halfW: 1.5, halfD: 2.5 },   // collision box (authored, not measured) — bigger/longer

  async build(scene, paintOverride = null) {
    const result = await SceneLoader.ImportMeshAsync('', '/assets/models/tanks/parts/', 'medium_hull_standard.glb', scene);
    const mountNode = result.transformNodes.find(n => n.name === this.mountEmpty);
    const mount = mountNode ? mountNode.getAbsolutePosition().clone() : null;

    const root = new TransformNode('hull_medium_root', scene);
    const meshes = result.meshes.filter(m => m.name !== '__root__');
    for (const m of meshes) m.setParent(root);

    applyModelPaint(meshes, PAINT, scene, paintOverride);
    return { root, meshes, mount, ringCenter: mount };
  },
};
